INSERT INTO public.psychometric_questions (id, sort_order, payload) VALUES
  ('q1', 1, $psy${"id":"q1","dim":"business","type":"scenario","bn":"আপনার এলাকায় হঠাৎ আপনার মতোই একই পণ্য বিক্রেতা একজন এসে দোকান খুলল। প্রথম কাজ কী করবেন?","en":"A competitor opens nearby. What is your first response?","options":[{"bn":"চিন্তা করব না, ব্যবসা চালিয়ে যাব","en":"Option 1","score":1},{"bn":"গ্রাহকদের সাথে সম্পর্ক আরও ভালো করব","en":"Option 2","score":2},{"bn":"পণ্যের মান ও সেবার মান বাড়াব","en":"Option 3","score":2},{"bn":"দাম কমিয়ে দেব যাতে বেশি গ্রাহক আসে","en":"Option 4","score":3},{"bn":"নতুন পণ্য বা সেবা যোগ করব","en":"Option 5","score":3},{"bn":"প্রতিযোগীর দোকান ও পণ্য পর্যবেক্ষণ করব","en":"Option 6","score":4},{"bn":"পুরনো গ্রাহকদের বিশেষ সুবিধা দেব","en":"Option 7","score":4},{"bn":"আমার ব্যবসার ধরন বা এলাকা পরিবর্তন করব","en":"Option 8","score":5}],"expectedMs":5500}$psy$::jsonb),
  ('q2', 2, $psy${"id":"q2","dim":"business","type":"scale","bn":"\"আমি সবসময় গ্রাহককে উন্নত সেবা দিতে চেষ্টা করি\" — এই কথার সাথে আপনি কতটুকু একমত?","en":"Assessment item (see Bangla).","scale":{"min":1,"max":5,"minBn":"একদমই একমত নই","maxBn":"সম্পূর্ণ একমত","minEn":"Low","maxEn":"High","steps":["একদমই একমত নই","একমত নই","মাঝামাঝি","একমত","সম্পূর্ণ একমত"]},"socialDesirability":true,"expectedMs":4000}$psy$::jsonb),
  ('q3', 3, $psy${"id":"q3","dim":"business","type":"scenario","bn":"আপনি কীভাবে জানেন কোন পণ্যটি বেশি বিক্রি হচ্ছে? (নিচ থেকে একটি বেছে নিন যা সবচেয়ে বেশি প্রযোজ্য।)","en":"Assessment item (see Bangla).","options":[{"bn":"প্রতিদিনের বিক্রির হিসাব খাতায় লিখে রাখি","en":"Option 1","score":1},{"bn":"কোন পণ্য বেশি দ্রুত শেষ হয় সেটা দেখি","en":"Option 2","score":2},{"bn":"গ্রাহকরা কোন পণ্যের কথা বেশি জিজ্ঞেস করে সেটা খেয়াল রাখি","en":"Option 3","score":2},{"bn":"অনুমানে বুঝতে পারি","en":"Option 4","score":3},{"bn":"মোবাইল অ্যাপ বা হিসাবের সফটওয়্যার ব্যবহার করি","en":"Option 5","score":4},{"bn":"মাসের শেষে স্টক গণনা করে বুঝি","en":"Option 6","score":4},{"bn":"কোনো নির্দিষ্ট পদ্ধতি নেই","en":"Option 7","score":5}],"expectedMs":5500}$psy$::jsonb),
  ('q4', 4, $psy${"id":"q4","dim":"business","type":"scenario","bn":"আপনার পণ্যের দাম কে ঠিক করে?","en":"Assessment item (see Bangla).","options":[{"bn":"আমি নিজে ঠিক করি","en":"Option 1","score":1},{"bn":"বাজারের সাথে মিলিয়ে ঠিক করি","en":"Option 2","score":2},{"bn":"সরবরাহকারী/পাইকার নির্ধারণ করে দেয়","en":"Option 3","score":2},{"bn":"পরিবারের সিনিয়র সদস্য ঠিক করেন","en":"Option 4","score":3},{"bn":"প্রতিযোগীর দামের উপর নির্ভর করে ঠিক করি","en":"Option 5","score":4},{"bn":"উৎপাদন খরচ বের করে লাভ যোগ করে ঠিক করি","en":"Option 6","score":4},{"bn":"এলাকার অন্য দোকানিদের সাথে মিলে ঠিক করি","en":"Option 7","score":5}],"expectedMs":5500}$psy$::jsonb),
  ('q5', 5, $psy${"id":"q5","dim":"business","type":"math","bn":"📊 হিসাবের প্রশ্ন: আপনার দোকানে দৈনিক বিক্রি ২,০০০ টাকা। পণ্য কিনতে লাগে ১,৫০০ টাকা। মাসে (৩০ দিন) মোট লাভ কত? সঠিক উত্তরটি বেছে নিন:","en":"Numerical reasoning (see Bangla).","options":[{"bn":"৯,০০০ টাকা","en":"Option 1","score":2},{"bn":"১২,০০০ টাকা","en":"Option 2","score":2},{"bn":"১৫,০০০ টাকা","en":"Option 3","score":5},{"bn":"১৮,০০০ টাকা","en":"Option 4","score":2},{"bn":"২০,০০০ টাকা","en":"Option 5","score":2},{"bn":"হিসাব করতে পারছি না","en":"Option 6","score":1}],"expectedMs":12000}$psy$::jsonb),
  ('q6', 6, $psy${"id":"q6","dim":"business","type":"math","bn":"📊 হিসাবের প্রশ্ন: আপনি ১২০ টাকায় একটি পণ্য কিনে ১৫০ টাকায় বিক্রি করলেন। মুনাফার হার কত? সঠিক উত্তরটি বেছে নিন:","en":"Numerical reasoning (see Bangla).","options":[{"bn":"২০%","en":"Option 1","score":2},{"bn":"২৫%","en":"Option 2","score":5},{"bn":"৩০%","en":"Option 3","score":2},{"bn":"৩৩%","en":"Option 4","score":2},{"bn":"১৫%","en":"Option 5","score":2},{"bn":"হিসাব করতে পারছি না","en":"Option 6","score":1}],"expectedMs":12000}$psy$::jsonb),
  ('q7', 7, $psy${"id":"q7","dim":"business","type":"scenario","bn":"ব্যবসায় মূলধন (পুঁজি) আর মুনাফার (লাভ) পার্থক্য কী বলে আপনি মনে করেন?","en":"Assessment item (see Bangla).","options":[{"bn":"দুটো একই জিনিস","en":"Option 1","score":1},{"bn":"মূলধন হলো ব্যবসার শুরুর টাকা, মুনাফা হলো বিক্রির পর বাড়তি আয়","en":"Option 2","score":5},{"bn":"মূলধন হলো ব্যাংকের টাকা, মুনাফা হলো নিজের টাকা","en":"Option 3","score":1},{"bn":"মূলধন মানে ঋণ, মুনাফা মানে সঞ্চয়","en":"Option 4","score":1},{"bn":"জানি না / স্পষ্ট ধারণা নেই","en":"Option 5","score":1}],"expectedMs":5500}$psy$::jsonb),
  ('q8', 8, $psy${"id":"q8","dim":"financial","type":"scenario","bn":"ব্যবসার পাশাপাশি আপনার বিকল্প আয়ের উৎস কী কী? (নিচ থেকে একটি বেছে নিন যা সবচেয়ে বেশি প্রযোজ্য।)","en":"Assessment item (see Bangla).","options":[{"bn":"কৃষি/চাষাবাদ","en":"Option 1","score":1},{"bn":"হাঁস-মুরগি বা গবাদিপশু পালন","en":"Option 2","score":2},{"bn":"ছোট চাকরি/খণ্ডকালীন কাজ","en":"Option 3","score":2},{"bn":"পরিবারের অন্য সদস্যের আয়","en":"Option 4","score":3},{"bn":"সেলাই/হস্তশিল্প/কুটিরশিল্প","en":"Option 5","score":3},{"bn":"বিদেশ থেকে রেমিট্যান্স","en":"Option 6","score":4},{"bn":"বাড়ি/জমি ভাড়া","en":"Option 7","score":4},{"bn":"অন্য কোনো ব্যবসা","en":"Option 8","score":5},{"bn":"কোনো বিকল্প আয় নেই","en":"Option 9","score":2}],"expectedMs":5500}$psy$::jsonb),
  ('q9', 9, $psy${"id":"q9","dim":"financial","type":"scenario","bn":"আপনার কাছে কোনটি বেশি জরুরি?","en":"Assessment item (see Bangla).","options":[{"bn":"পরিবারের দৈনন্দিন চাহিদা মেটানো","en":"Option 1","score":1},{"bn":"পরিবারের আয় বাড়ানো","en":"Option 2","score":2},{"bn":"ব্যবসার মূলধন বাড়ানো","en":"Option 3","score":3},{"bn":"সন্তানদের পড়াশোনা ও ভবিষ্যৎ নিশ্চিত করা","en":"Option 4","score":3},{"bn":"ঋণমুক্ত হওয়া","en":"Option 5","score":4},{"bn":"বাড়ি বা সম্পদ তৈরি করা","en":"Option 6","score":5}],"expectedMs":5500}$psy$::jsonb),
  ('q10', 10, $psy${"id":"q10","dim":"financial","type":"scale","bn":"\"প্রতি মাসে আমি আয়ের কিছু অংশ সঞ্চয় করি\" — এই কথার সাথে আপনি কতটুকু একমত?","en":"Assessment item (see Bangla).","scale":{"min":1,"max":5,"minBn":"একদমই না","maxBn":"সবসময়","minEn":"Low","maxEn":"High","steps":["একদমই না","হঠাৎ হঠাৎ","মাঝে মাঝে","প্রায়ই","সবসময়"]},"socialDesirability":true,"expectedMs":4000}$psy$::jsonb),
  ('q11', 11, $psy${"id":"q11","dim":"financial","type":"scenario","bn":"কত শতাংশ মুনাফা (Profit %) হলে আপনি ব্যবসা টিকিয়ে রাখতে পারবেন?","en":"Assessment item (see Bangla).","options":[{"bn":"১০% এর কম","en":"Option 1","score":1},{"bn":"১০% — ২০%","en":"Option 2","score":2},{"bn":"২১% — ৩০%","en":"Option 3","score":3},{"bn":"৩১% — ৫০%","en":"Option 4","score":3},{"bn":"৫০% এর বেশি","en":"Option 5","score":4},{"bn":"জানি না / হিসাব করিনি","en":"Option 6","score":2}],"expectedMs":5500}$psy$::jsonb),
  ('q12', 12, $psy${"id":"q12","dim":"financial","type":"scenario","bn":"প্রতি মাসে কত টাকা পুঁজি খাটিয়ে ব্যবসা করেন? (নিচে একটি বেছে নিন)","en":"Monthly capital you deploy in business (select one band).","options":[{"bn":"পুঁজি: ৫,০০০ টাকার কম","en":"First","score":1},{"bn":"পুঁজি: ৫,০০০ — ২০,০০০","en":"Second","score":2},{"bn":"পুঁজি: ২০,০০১ — ৫০,০০০","en":"Third","score":3},{"bn":"পুঁজি: ৫০,০০১ — ১ লাখ","en":"Fourth","score":4},{"bn":"পুঁজি: ১ লাখের বেশি","en":"Fifth","score":5}],"expectedMs":5000}$psy$::jsonb),
  ('q13', 13, $psy${"id":"q13","dim":"financial","type":"scenario","bn":"মাসিক মোট বিক্রি/টার্নওভার কত? (নিচে একটি বেছে নিন)","en":"Approximate monthly turnover (select one band).","options":[{"bn":"বিক্রি: ১০,০০০ টাকার কম","en":"First","score":1},{"bn":"বিক্রি: ১০,০০০ — ৩০,০০০","en":"Second","score":2},{"bn":"বিক্রি: ৩০,০০১ — ৭৫,০০০","en":"Third","score":3},{"bn":"বিক্রি: ৭৫,০০১ — ২ লাখ","en":"Fourth","score":4},{"bn":"বিক্রি: ২ লাখের বেশি","en":"Fifth","score":5}],"expectedMs":5000}$psy$::jsonb),
  ('q14', 14, $psy${"id":"q14","dim":"risk","type":"scenario","bn":"কেউ আপনাকে বলল: \"৫০,০০০ টাকা বিনিয়োগ করলে ২ মাসে ৭৫,০০০ পাবেন।\" আপনি কী করবেন?","en":"Assessment item (see Bangla).","options":[{"bn":"সাথে সাথে বিনিয়োগ করব, সুযোগ হাতছাড়া করব না","en":"Option 1","score":1},{"bn":"আগে ভালো করে খোঁজ-খবর নেব, তারপর সিদ্ধান্ত নেব","en":"Option 2","score":5},{"bn":"পরিবারের সাথে আলোচনা করব","en":"Option 3","score":5},{"bn":"বিশ্বস্ত কারো কাছ থেকে পরামর্শ নেব","en":"Option 4","score":5},{"bn":"এত বেশি লাভের কথা শুনলে সন্দেহ হয়, বিনিয়োগ করব না","en":"Option 5","score":5},{"bn":"সামান্য পরিমাণ দিয়ে পরীক্ষামূলকভাবে করে দেখব","en":"Option 6","score":5},{"bn":"সরাসরি না করে দেব","en":"Option 7","score":5}],"expectedMs":5500}$psy$::jsonb),
  ('q15', 15, $psy${"id":"q15","dim":"risk","type":"scale","bn":"\"সুযোগ পেলে আমি গ্যারান্টি ছাড়াও ঝুঁকি নিতে রাজি\" — এর সাথে আপনি কতটুকু একমত?","en":"Assessment item (see Bangla).","scale":{"min":1,"max":5,"minBn":"একদমই না","maxBn":"সম্পূর্ণ রাজি","minEn":"Low","maxEn":"High","steps":["একদমই না","খুব কমই","পরিস্থিতি বুঝে","সাধারণত রাজি","সম্পূর্ণ রাজি"]},"expectedMs":4000}$psy$::jsonb),
  ('q16', 16, $psy${"id":"q16","dim":"risk","type":"scenario","bn":"ধরুন, ঋণের ১০ হাজার টাকা আপনার হাতে আছে। ঝুঁকিপূর্ণ নতুন কাজে কতটুকু বিনিয়োগ করবেন?","en":"Assessment item (see Bangla).","options":[{"bn":"কিছুই না, পুরোটা নিরাপদ কাজে লাগাব","en":"Option 1","score":1},{"bn":"১,০০০ — ২,০০০ টাকা (১০-২০%)","en":"Option 2","score":2},{"bn":"২,০০১ — ৪,০০০ টাকা (২০-৪০%)","en":"Option 3","score":3},{"bn":"৪,০০১ — ৬,০০০ টাকা (৪০-৬০%)","en":"Option 4","score":3},{"bn":"৬,০০১ — ৮,০০০ টাকা (৬০-৮০%)","en":"Option 5","score":4},{"bn":"প্রায় পুরোটাই (৮০% এর বেশি)","en":"Option 6","score":5}],"expectedMs":5500}$psy$::jsonb),
